//! Structured jobs embedded in `agent_tasks.execution_prompt` for squad
//! pipeline `script` / `git_op` nodes. Local watcher detects the prefix and
//! runs the job instead of a coding agent.

use serde::{Deserialize, Serialize};
use uuid::Uuid;

/// Prefix marking an execution_prompt as a pipeline job (not an agent prompt).
pub const PIPELINE_JOB_PREFIX: &str = "__vk_pipeline_job__:";

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum PipelineJobKind {
    Script,
    GitOp,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct PipelineJobSpec {
    pub kind: PipelineJobKind,
    /// Shell command for `script` nodes.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub command: Option<String>,
    /// `rebase` | `merge` | `push` | `create_pr` for `git_op` nodes.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub op: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub target_branch: Option<String>,
    /// Prefer an existing local workspace from a prior coding step.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub local_workspace_id: Option<Uuid>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub label: Option<String>,
}

impl PipelineJobSpec {
    pub fn encode(&self) -> Result<String, serde_json::Error> {
        Ok(format!(
            "{}{}",
            PIPELINE_JOB_PREFIX,
            serde_json::to_string(self)?
        ))
    }

    pub fn parse(prompt: &str) -> Option<Self> {
        let trimmed = prompt.trim();
        let json = trimmed.strip_prefix(PIPELINE_JOB_PREFIX)?;
        serde_json::from_str(json.trim()).ok()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn roundtrip_script() {
        let spec = PipelineJobSpec {
            kind: PipelineJobKind::Script,
            command: Some("pnpm run check".into()),
            op: None,
            target_branch: None,
            local_workspace_id: None,
            label: Some("verify".into()),
        };
        let encoded = spec.encode().unwrap();
        assert!(encoded.starts_with(PIPELINE_JOB_PREFIX));
        let parsed = PipelineJobSpec::parse(&encoded).unwrap();
        assert_eq!(parsed, spec);
    }
}

/**
 * Server-side store for global-copilot (agent_id: null) model config, keyed by
 * project_id. Lets multiple devices share one config; api_key stays server-side.
 *
 * ponytail: single JSON file, whole-map read/write. Fine for a handful of
 * projects on a single sidecar instance; move to the remote DB if it ever needs
 * multi-instance or per-user scoping.
 */
import { promises as fs } from "node:fs";
import path from "node:path";

export type CopilotModelConfig = {
  base_url?: string;
  api_key?: string;
  model?: string;
};

const FILE =
  process.env.VK_COPILOT_CONFIG_FILE ??
  path.join(process.cwd(), ".copilot-model-config.json");

type Store = Record<string, CopilotModelConfig>;

async function readAll(): Promise<Store> {
  try {
    return JSON.parse(await fs.readFile(FILE, "utf8")) as Store;
  } catch {
    return {};
  }
}

export async function getConfig(
  projectId: string,
): Promise<CopilotModelConfig | null> {
  const all = await readAll();
  return all[projectId] ?? null;
}

/** Merge patch: only overwrites provided keys. Empty string clears a key. */
export async function upsertConfig(
  projectId: string,
  patch: CopilotModelConfig,
): Promise<CopilotModelConfig> {
  const all = await readAll();
  const next: CopilotModelConfig = { ...all[projectId] };
  for (const k of ["base_url", "api_key", "model"] as const) {
    const v = patch[k];
    if (v === undefined) continue;
    if (v.trim() === "") delete next[k];
    else next[k] = v.trim();
  }
  all[projectId] = next;
  await fs.writeFile(FILE, JSON.stringify(all, null, 2), "utf8");
  return next;
}

